/** Сумма в рублях: разделители тысяч, фиксированные знаки после запятой, знак ₽. */
export function formatRubleAmount(amount: number, fractionDigits = 2): string {
  const formatter = new Intl.NumberFormat("ru-RU", {
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  });
  return `${formatter.format(amount)} ₽`;
}

/** Границы месяца для фильтра периода. */
export function getMonthBounds(year: number, month: number) {
  const first = new Date(year, month, 1);
  const last = new Date(year, month + 1, 0);
  const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  return { from: iso(first), to: iso(last) };
}

export function dateToYmd(value: Date): string {
  const year = value.getFullYear();
  const month = (value.getMonth() + 1).toString().padStart(2, "0");
  const day = value.getDate().toString().padStart(2, "0");
  return [year, month, day].join("-");
}

/** После деплоя старые чанки пропадают — динамический import падает. */
export function isChunkLoadFailure(err: unknown): boolean {
  const text = err instanceof Error ? err.message : `${err}`;
  return /dynamically imported module|Importing a module script failed|Unable to preload CSS/i.test(text);
}

const plural = new Intl.PluralRules("ru-RU");

export function ruPluralUnit(n: number, one: string, few: string, many: string): string {
  switch (plural.select(n)) {
    case "one": return one;
    case "few": return few;
    default: return many;
  }
}

export function saveBlobAsFile(data: Blob, name: string) {
  const href = window.URL.createObjectURL(data);
  const a = document.createElement("a");
  a.setAttribute("href", href);
  a.setAttribute("download", name);
  document.body.append(a);
  a.click();
  a.remove();
  window.URL.revokeObjectURL(href);
}

internal static class ReportConfigJson
{
  public static IReadOnlyList<string> GetStringList(JsonElement obj, string name)
  {
    var result = new List<string>();
    if (obj.TryGetProperty(name, out var value) && value.ValueKind == JsonValueKind.Array)
    {
      foreach (var item in value.EnumerateArray())
      {
        if (item.ValueKind == JsonValueKind.String) result.Add(item.GetString()!);
      }
    }
    return result;
  }
}

export const saveFileFromBlob = (blob: Blob, filename: string) => {
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = filename;
  link.click();
  setTimeout(() => URL.revokeObjectURL(link.href), 0);
};

/** Длительность отпуска в календарных днях, обе границы включены. */
export function countDaysInclusive(from: string, to: string): number {
  const a = new Date(from + "T00:00:00Z").getTime();
  const b = new Date(to + "T00:00:00Z").getTime();
  return Math.floor((b - a) / (24 * 60 * 60 * 1000)) + 1;
}

export function getRoleFromToken(jwt?: string | null) {
  if (!jwt) return null;
  const [, payload] = jwt.split(".");
  if (!payload) return null;
  try {
    const json = atob(payload.replace(/-/g, "+").replace(/_/g, "/"));
    const claims = JSON.parse(json);
    return typeof claims.role === "string" ? parseRole(claims.role) : null;
  } catch {
    return null;
  }
}

export function checkUploadFile(file: File, maxBytes = 20 * 1024 * 1024, types = ["application/pdf", "image/jpeg", "image/png"]): string | null {
  if (!types.includes(file.type)) return "common:fileErrors.unsupportedFormat";
  if (file.size > maxBytes) return "common:fileErrors.tooLarge20";
  return null;
}

export function formatDateRu(value: string, lang: "ru" | "en" = "ru") {
  return new Date(value).toLocaleDateString(lang === "ru" ? "ru-RU" : "en-GB", {
    day: "2-digit", month: "2-digit", year: "numeric",
  });
}

internal static class LeaveYearDays
{
  public static int DaysWithinYear(DateOnly from, DateOnly to, int year)
  {
    var start = new DateOnly(year, 1, 1);
    var end = new DateOnly(year, 12, 31);
    var s = from > start ? from : start;
    var e = to < end ? to : end;
    return Math.Max(0, e.DayNumber - s.DayNumber + 1);
  }
}

internal sealed class LeaveOrderDocxBuilder
{
  private static void AddBlankParagraph(Body body)
  {
    body.AppendChild(new Paragraph());
  }
}

export function readLocalStorageSafe(key: string): string | null {
  try {
    return window.localStorage ? window.localStorage.getItem(key) : null;
  } catch (e) {
    return null;
  }
}

export function toSafeHref(input: string): string | null {
  const s = input.trim();
  if (s === "") return null;
  if (/^(https?:|mailto:)/i.test(s)) return s;
  if (/^[a-z][\w+.-]*:/i.test(s)) return null;
  if (/^[^\s/]+@[^\s/]+$/.test(s)) return "mailto:" + s;
  return "https://" + s;
}

export function exportProcessJson(payload: object, processCode: string, version: number) {
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = `process-${processCode}-v${version}.json`;
  link.click();
  URL.revokeObjectURL(link.href);
}

export const trimToUndefined = (s: string): string | undefined => {
  const t = s.trim();
  return t.length > 0 ? t : undefined;
};

internal sealed class AssistantRateGuard(TimeProvider clock)
{
  private static readonly ConcurrentDictionary<Guid, List<DateTimeOffset>> History = new();

  public void ThrottleUserStarts(Guid userId, int limit, TimeSpan window)
  {
    var now = clock.GetUtcNow();
    var list = History.GetOrAdd(userId, _ => []);
    lock (list)
    {
      list.RemoveAll(t => now - t >= window);
      if (list.Count >= limit) throw new BpmnAssistantException("assistant_rate_limited", 429);
      list.Add(now);
    }
  }
}

internal static class BpmnAssistantHistoryRequestJsonParser
{
  private static string RequireStringMember(IReadOnlyDictionary<string, JsonElement> fields, string key)
  {
    if (!fields.TryGetValue(key, out var el) || el.ValueKind != JsonValueKind.String)
      throw new BpmnAssistantRequestFormatException();
    return el.GetString()!;
  }
}
